     5→
     6→import { login } from "../../shopify.server";
     7→import { loginErrorMessage } from "./error.server";
     8→
     9→export const loader = async ({ request }: LoaderFunctionArgs) => {
    10→  const errors = loginErrorMessage(await login(request));
    11→
    12→  return { errors };
    13→};
    14→
    15→export const action = async ({ request }: ActionFunctionArgs) => {
    16→  const errors = loginErrorMessage(await login(request));
    17→
    18→  return {
    19→    errors,
    20→  };
    21→};
    22→
    23→export default function Auth() {
    24→  const loaderData = useLoaderData<typeof loader>();
    25→  const actionData = useActionData<typeof action>();
    26→  const [shop, setShop] = useState("");
    27→  const { errors } = actionData || loaderData;
    28→
    29→  return (
    30→    <AppProvider embedded={false}>
    31→      <s-page>
    32→        <Form method="post">
    33→        <s-section heading="Log in">
    34→          <s-text-field
    35→            name="shop"
    36→            label="Shop domain"
    37→            details="example.myshopify.com"
    38→            value={shop}
    39→            onChange={(e) => setShop(e.currentTarget.value)}
    40→            autocomplete="on"
    41→            error={errors.shop}
    42→          ></s-text-field>
    43→          <s-button type="submit">Log in</s-button>
    44→        </s-section>
